/**
 * @description Streaming context-window usage update for a session.
 * @type object
*/
export type SessionUsageUpdate = {
    /**
     * @minLength 0
     * @type integer
    */
    used: number;
    /**
     * @minLength 0
     * @type integer
    */
    contextLimit: number;
    /**
     * @minLength 0
     * @type integer
    */
    accumulatedInputTokens: number;
    /**
     * @minLength 0
     * @type integer
    */
    accumulatedOutputTokens: number;
    /**
     * @description
     * Format: `double`
     * @type number | undefined
    */
    accumulatedCost?: number | null;
};

export type StatusMessage = ({
    message: string;
    type: "notice";
} | {
    message: string;
    type: "progress";
});

/**
 * @description Live UI/session status. This is not conversation transcript content, and\nshould not be persisted or replayed as history.
 * @type object
*/
export type StatusMessageUpdate = {
    status: StatusMessage;
};

/**
 * @description Wire mirror of the conversation `CostSource`.
*/
export type CostSourceData = ("provider_reported" | "estimated");

/**
 * @description Wire mirror of the conversation `MessageUsage` (this crate cannot depend on\nbcaip-provider-types); field names and serde casing MUST stay in parity.
 * @type object
*/
export type MessageUsageData = {
    inputTokens?: number | null;
    outputTokens?: number | null;
    totalTokens?: number | null;
    cacheReadTokens?: number | null;
    cacheWriteTokens?: number | null;
    /**
     * @description
     * Format: `double`
     * @type number | undefined
    */
    cost?: number | null;
    costSource?: (CostSourceData | null);
    /**
     * @description Wall-clock generation time, used by the client for a tokens/sec readout.
     * @minLength 0
     * @type integer | undefined
    */
    elapsedMs?: number | null;
    /**
     * @minLength 0
     * @type integer | undefined
    */
    timeToFirstTokenMs?: number | null;
    /**
     * @description Usage from a compaction/summarization call rather than a normal turn.
     * @default false
     * @type boolean | undefined
    */
    isCompaction?: boolean;
};

/**
 * @description Per-message token usage/cost/timing, keyed by the message id used for\nchunk matching. Sent live after a turn\'s messages and on replay.
 * @type object
*/
export type MessageUsageUpdate = {
    messageId?: string | null;
    /**
     * @description Wire mirror of the conversation `MessageUsage` (this crate cannot depend on\nbcaip-provider-types); field names and serde casing MUST stay in parity.
     * @type object
    */
    usage: MessageUsageData;
};

export const liveVoiceInteractionOutcome = {
    stopped: "stopped",
    failed: "failed"
} as const;

export type LiveVoiceInteractionOutcomeKey = (typeof liveVoiceInteractionOutcome)[keyof typeof liveVoiceInteractionOutcome];

export type LiveVoiceInteractionEndedUpdate = {
    interactionId: string;
    outcome: LiveVoiceInteractionOutcomeKey;
};

/**
 * @description Discriminated union of bcaip-specific session update payloads.\nVariant tag matches ACP\'s convention (`sessionUpdate: \"<snake_case>\"`).\n\n`discriminator.mapping` is what makes TS codegen (`@hey-api/openapi-ts`)\nemit the correct snake_case tag value even when this enum has a single\nvariant. Add a mapping entry per variant.
*/
export type BcaipSessionUpdate = ((SessionUsageUpdate & {
    sessionUpdate: "usage_update";
}) | (StatusMessageUpdate & {
    sessionUpdate: "status_message";
}) | (MessageUsageUpdate & {
    sessionUpdate: "message_usage";
}) | (LiveVoiceInteractionEndedUpdate & {
    sessionUpdate: "live_voice_interaction_ended";
}));

/**
 * @description Bcaip-custom session update notification — a parallel to ACP\'s\n`session/update` carrying bcaip-specific update variants.
 * @type object
*/
export type BcaipSessionNotificationUnstable = {
    sessionId: string;
    /**
     * @description Discriminated union of bcaip-specific session update payloads.\nVariant tag matches ACP\'s convention (`sessionUpdate: \"<snake_case>\"`).\n\n`discriminator.mapping` is what makes TS codegen (`@hey-api/openapi-ts`)\nemit the correct snake_case tag value even when this enum has a single\nvariant. Add a mapping entry per variant.
    */
    update: BcaipSessionUpdate;
};

/**
 * @description Dedicated provider notification for OAuth device-code flow.\nSent during provider authentication when the ACP client supports\n`bcaip.customNotifications` — avoids a fake empty session ID.
 * @type object
*/
export type ProviderDeviceCodeNotificationUnstable = {
    providerId: string;
    userCode: string;
    verificationUri: string;
    /**
     * @minLength 0
     * @type integer
    */
    expiresIn: number;
};

/**
 * @description Ask the client to provide values for a recipe\'s parameters.
 * @type object
*/
export type RequestRecipeParamsUnstable = {
    sessionId: string;
    parameters: RecipeParameterDto[];
    parameterScopeId?: string | null;
};

export const recipeParamsAction = {
    submit: "submit",
    cancel: "cancel"
} as const;

export type RecipeParamsActionKey = (typeof recipeParamsAction)[keyof typeof recipeParamsAction];

export type RecipeParamsResponseUnstable = {
    /**
     * @default 'submit'
     * @type string | undefined
    */
    action?: RecipeParamsActionKey;
    /**
     * @default [object Object]
     * @type object | undefined
    */
    values?: {
        [key: string]: string;
    };
};

